package com.infinitylibrary.builder;
import com.infinitylibrary.InfinityLibraryPlugin;import com.infinitylibrary.community.ManagedDialogs;import com.infinitylibrary.model.RoomType;import org.bukkit.entity.Player;import net.kyori.adventure.text.Component;import io.papermc.paper.registry.data.dialog.input.DialogInput;import java.util.*;
/** Native server dialogs for common capture/configuration flows; no companion mod required. */
public final class BuilderFlows {
 private final InfinityLibraryPlugin plugin;public BuilderFlows(InfinityLibraryPlugin p){plugin=p;}
 private void admin(Player p){if(!p.hasPermission("infinitylibrary.admin"))throw new IllegalArgumentException("Builder permission required");}
 private DialogInput text(String id,String label,String value,int max){return DialogInput.text(id,Component.text(label)).initial(value).maxLength(max).build();}
 public void saveRoom(Player p){admin(p);long revision=plugin.getAuthoringManager().revision(p);List<ManagedDialogs.Button> buttons=new ArrayList<>();for(var type:List.of(RoomType.FILLER,RoomType.READ,RoomType.RENTABLE,RoomType.PUBLIC_WRITING,RoomType.STARTING))buttons.add(new ManagedDialogs.Button(type==RoomType.READ?"READING":type.name(),r->{admin(p);String id=r.getText("id");Runnable save=()->{admin(p);if(plugin.getAuthoringManager().revision(p)!=revision)throw new IllegalArgumentException("Selection changed; reopen Save selected room");plugin.getRoomManager().capture(p,id,type,plugin.getSelectionManager().stagedConnections(p));plugin.getAuthoringManager().saved(p,id);p.sendMessage("Saved room "+id+" as "+type);plugin.getGuiManager().openRoomDetails(p,id);};var old=plugin.getRoomManager().getActive(id);if(old.isEmpty())save.run();else{String version=plugin.getBuilderBridge().version(old.get());plugin.getManagedDialogs().show(p,"Replace unused template?","Existing built templates stay protected. Choose another ID to retain both versions.",List.of(),List.of(new ManagedDialogs.Button("Replace",response->{var current=plugin.getRoomManager().getActive(id).orElseThrow();if(!version.equals(plugin.getBuilderBridge().version(current)))throw new IllegalArgumentException("Template changed; reopen the capture dialog");save.run();}),new ManagedDialogs.Button("Cancel",response->plugin.getGuiManager().openBuilderMenu(p))));}}));buttons.add(new ManagedDialogs.Button("Cancel",r->plugin.getGuiManager().openBuilderMenu(p)));plugin.getManagedDialogs().show(p,"Save selected room","Select the room's corners and doors first. Choose the role to capture the template.",List.of(text("id","Room ID","my_room",64)),buttons);}
 public void decoration(Player p){admin(p);plugin.getManagedDialogs().form(p,"Decoration area settings",List.of(text("category","Category","general",64),text("area","Area ID prefix","area",48),text("fill","EXACT or PACKED","EXACT",8),text("gap","Gap percent (PACKED)","0",8)),r->{admin(p);String category=r.getText("category");plugin.getAuthoringManager().category(p,category);plugin.getPropManager().mode(p,category,Double.parseDouble(r.getText("gap")),r.getText("area"),true,false,com.infinitylibrary.props.PropArea.FillMode.valueOf(r.getText("fill").toUpperCase(Locale.ROOT)));plugin.getAuthoringManager().activate(p,"decoration");p.sendMessage("Select the two decoration-area corners. Exact mode requires matching size and category.");},()->plugin.getGuiManager().openBuilderMenu(p));}
 public void connection(Player p){admin(p);plugin.getManagedDialogs().form(p,"Connection settings",List.of(text("prefix","Connection ID prefix","door",48),text("floor","Floor index","0",8)),r->{admin(p);plugin.getSelectionManager().setConnectionPrefix(p,r.getText("prefix"));plugin.getSelectionManager().setConnectionFloor(p,Integer.parseInt(r.getText("floor")));plugin.getAuthoringManager().activate(p,"connection");p.sendMessage("Select the full doorway rectangle on the room boundary.");},()->plugin.getGuiManager().openBuilderMenu(p));}
 public void diversity(Player p){admin(p);List<ManagedDialogs.Button> buttons=List.of(new ManagedDialogs.Button("Target + source",r->{admin(p);plugin.getDiversityManager().mode(p,r.getText("area"),r.getText("variant"),Double.parseDouble(r.getText("weight")));plugin.getAuthoringManager().activate(p,"diversity");}),new ManagedDialogs.Button("Additional source",r->{admin(p);plugin.getDiversityManager().variant(p,r.getText("area"),r.getText("variant"),Double.parseDouble(r.getText("weight")));plugin.getAuthoringManager().activate(p,"diversity");}),new ManagedDialogs.Button("Variant door",r->{admin(p);var wand=plugin.getDiversityManager().connectionWand(p,r.getText("area"),r.getText("variant"),r.getText("facing"),Integer.parseInt(r.getText("floor")),r.getText("door"));plugin.getBookStorageManager().returnItem(p,wand);}),new ManagedDialogs.Button("Cancel",r->plugin.getGuiManager().openBuilderMenu(p)));plugin.getManagedDialogs().show(p,"Room Diversity","Capture a target and an equally sized source. Additional sources retain the target. Capture a source before assigning its variant doors.",List.of(text("area","Area ID","area_1",48),text("variant","Variant ID","variant_1",48),text("weight","Variant weight","1",12),text("facing","Variant door direction","NORTH",8),text("floor","Variant floor index","0",8),text("door","Variant door ID","door",48)),buttons);}
 public void configure(Player p,String tool){admin(p);switch(tool){case "room"->saveRoom(p);case "connection"->connection(p);case "decoration"->decoration(p);case "diversity","diversity_connection"->diversity(p);case "shelf","table","seat"->plugin.getManagedDialogs().form(p,"Region category",List.of(text("category","Category","general",64)),r->{admin(p);plugin.getAuthoringManager().category(p,r.getText("category"));plugin.getAuthoringManager().activate(p,tool);},()->plugin.getGuiManager().openBuilderTools(p));case "variation"->plugin.getManagedDialogs().form(p,"Legacy variation settings",List.of(text("category","Category","general",64),text("chance","Chance percent","100",8),text("id","ID prefix","variation",48)),r->{admin(p);plugin.getSelectionManager().setVariationSettings(p,r.getText("category"),Double.parseDouble(r.getText("chance")),r.getText("id"));plugin.getAuthoringManager().activate(p,"variation");},()->plugin.getGuiManager().openBuilderTools(p));default->throw new IllegalArgumentException("Unknown tool");}}
}
